data.query:
query ProductionSetupOutput(
  $wherePSO: ProductionSetupOutputWhereInput 
  $whereWU:WorkunitWhereInput
  $whereP:ProductionSetupBomWhereInput
  ) {
  productionSetupOutput(where: $wherePSO) {
    edges {
      node {
        id
        workOrderProcessId
        productionSetupBoms (where: $whereP){
          edges {
            node {
              componentProductId
              wip
            }
          }
        }
      }
    }
  }
  workunit(where:$whereWU){
    edges {
      node {
        id
        scheduleGroupId
      }
    }
  }
}

