branches.transform:
/* (
  $workunit := workunit.edges.node;
  $mode := $state.context.REQUEST.DATA.modeId;
  $currentMode := $workunit.currentStateHistory.modeId;
  $coalesce([$mode,$workunit.currentStateHistory.modeId]) = "Production" ?
  $state.context.REQUEST.DATA.stateId in $workunit.productionStateList.stateListStates.edges.node.stateId
  :
  $coalesce([$mode,$workunit.currentStateHistory.modeId]) = "Changeover" ?
  $state.context.REQUEST.DATA.stateId in $workunit.changeoverStateList.stateListStates.edges.node.stateId
  :
  $coalesce([$mode,$workunit.currentStateHistory.modeId]) = "Maintenance" ?
  $state.context.REQUEST.DATA.stateId in $workunit.maintenanceStateList.stateListStates.edges.node.stateId
  :
  $coalesce([$mode,$workunit.currentStateHistory.modeId]) = "Idle" ?
  $state.context.REQUEST.DATA.stateId in $workunit.idleStateList.stateListStates.edges.node.stateId
  :
  $coalesce([$mode,$workunit.currentStateHistory.modeId]) = "Disabled" ?
  $state.context.REQUEST.DATA.stateId in $workunit.disabledStateList.stateListStates.edges.node.stateId
  :
  $coalesce([$mode,$workunit.currentStateHistory.modeId]) = "Other" ?
  $state.context.REQUEST.DATA.stateId in $workunit.otherStateList.stateListStates.edges.node.stateId
) ~> $not
 */

(
  $workunit := workunit.edges.node;
  $newMode := $state.context.REQUEST.DATA.modeId;
  $currentMode := $workunit.currentStateHistory.modeId;
  $mode := $coalesce([$newMode,$currentMode]);
  $modeStateList := $lowercase($mode) & "StateList";
  $state.context.REQUEST.DATA.stateId in $workunit.$eval($modeStateList).stateListStates.edges.node.stateId;
) ~> $not

