query ProductionHistory($where: ProductionHistoryWhereInput, $orderBy: [ProductionHistoryOrderByInput!], $first: Int, $after: String) {
  productionHistory(
    where: $where
    orderBy: $orderBy
    first: $first
    after: $after
  ) {
    edges {
      node {
        id
        number
        quantity
        serial
        occurAt
        workOrderProcessDistribution{
          workOrderProcessId
          workOrderProcess{
            workOrder{
              workOrderProcesses{
                edges{
                  node{
                    id
                    sequence
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

